import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import type { Repository } from 'typeorm';
import { ownerSqlWhere, type OwnerScope } from '../core/owner-context.js';
import { BillPayment } from './entities/bill-payment.entity.js';

interface RawExistsRow {
  found: number | string;
}

/**
 * Tells whether a transaction was generated by a bill payment, in its own
 * fakeable class (raw SQL): unit and e2e specs fake it, the MySQL integration
 * spec covers the real SQL. A `bank_bill_payments` row has no owner columns —
 * it inherits its owner from its source account — so the lookup joins
 * `bank_accounts` on `source_account_id` and goes through the owner filter: a
 * payment of another owner or context never counts.
 */
@Injectable()
export class PaymentGeneratedQuery {
  private readonly billPaymentRepository: Repository<BillPayment>;

  /**
   * @param {Repository<BillPayment>} billPaymentRepository - The bill-payment repository (read-only here).
   */
  constructor(@InjectRepository(BillPayment) billPaymentRepository: Repository<BillPayment>) {
    this.billPaymentRepository = billPaymentRepository;
  }

  /**
   * Runs **one** owner-scoped `EXISTS` over the three transaction references
   * (`payment_`, `withdrawal_`, `charge_transaction_id`, each FK-indexed).
   * @param {OwnerScope} owner - The data owner scope.
   * @param {number} transactionId - The transaction id.
   * @returns {Promise<boolean>} `true` when one of the owner's bill payments references the transaction.
   */
  async isPaymentGenerated(owner: OwnerScope, transactionId: number): Promise<boolean> {
    const ownerFilter = ownerSqlWhere(owner, 'a');
    const rows: RawExistsRow[] = await this.billPaymentRepository.query(
      `SELECT EXISTS (
         SELECT 1
           FROM bank_bill_payments p
           JOIN bank_accounts a ON a.id = p.source_account_id
          WHERE (p.payment_transaction_id = ? OR p.withdrawal_transaction_id = ? OR p.charge_transaction_id = ?)
            AND ${ownerFilter.sql}
       ) AS found`,
      [transactionId, transactionId, transactionId, ...ownerFilter.params],
    );

    return Number(rows[0]?.found) === 1;
  }
}
